// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router gin.IRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, GinServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router gin.IRouter, si ServerInterface, options GinServerOptions) {
	errorHandler := options.ErrorHandler
	if errorHandler == nil {
		errorHandler = func(c *gin.Context, err error, statusCode int) {
			c.JSON(statusCode, gin.H{"msg": err.Error()})
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandler:       errorHandler,
	}

	router.GET(options.BaseURL+"/admin/activities", wrapper.GetAppointmentsByTimeRangeOrCustomer)
	router.POST(options.BaseURL+"/admin/activities", wrapper.CreateAgendaActivity)
	router.DELETE(options.BaseURL+"/admin/activities/:activityId", wrapper.DeleteActivity)
	router.GET(options.BaseURL+"/admin/activities/:activityId", wrapper.GetActivityById)
	router.PUT(options.BaseURL+"/admin/activities/:activityId", wrapper.UpdateActivity)
	router.POST(options.BaseURL+"/admin/activities/:activityId/reminder/resend", wrapper.ResendReminder)
	router.POST(options.BaseURL+"/admin/services", wrapper.CreateService)
	router.GET(options.BaseURL+"/admin/services/all", wrapper.GetAllServices)
	router.GET(options.BaseURL+"/admin/services/search", wrapper.SearchService)
	router.PATCH(options.BaseURL+"/admin/services/:serviceId", wrapper.UpdateService)
	router.GET(options.BaseURL+"/insight/customer-cancellation-ranking", wrapper.GetCustomerCancelRanking)
	router.GET(options.BaseURL+"/insight/customer-ranking", wrapper.GetCustomerRanking)
	router.GET(options.BaseURL+"/insight/overview", wrapper.GetInsightOverview)
}

